# --------------------------------------------------------------------
# CUDA source implementing L2‑norm across dimension 1 (row‑wise)
# --------------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cmath>

constexpr int BLOCK_SIZE = 256;

/*
 * Row‑wise L2‑normalisation of a (batch, dim) matrix of half‑precision numbers.
 * The result is written to `output`.  Both tensors must be contiguous and on the
 * same CUDA device.
 */
template <int BS>
__global__ void l2norm_kernel(const __half* __restrict__ input,
                              __half* __restrict__ output,
                              int dim) {
    const int row = blockIdx.x;                 // one block per row
    const int tid = threadIdx.x;                // thread index inside the block

    const __half* row_in  = input  + (size_t)row * dim;
    __half*       row_out = output + (size_t)row * dim;

    // ----------------------------------------------------------------
    // 1) Compute sum of squares of the row (in float for precision)
    // ----------------------------------------------------------------
    float sum = 0.0f;
    for (int col = tid; col < dim; col += BS) {
        __half v = row_in[col];
        float f = __half2float(v);
        sum += f * f;
    }

    // ----------------------------------------------------------------
    // 2) Reduce partial sums within the block
    // ----------------------------------------------------------------
    __shared__ float shm[BS];
    shm[tid] = sum;
    __syncthreads();

    // tree‑based reduction (BS is a power‑of‑two ≤ 256)
    for (int stride = BS / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            shm[tid] += shm[tid + stride];
        }
        __syncthreads();
    }

    // ----------------------------------------------------------------
    // 3) Normalise the row using the computed norm
    // ----------------------------------------------------------------
    float norm = sqrtf(shm[0]) + 1e-6f;   // epsilon avoids division by zero
    float inv_norm = 1.0f / norm;

    for (int col = tid; col < dim; col += BS) {
        __half v = row_in[col];
        float f = __half2float(v) * inv_norm;
        row_out[col] = __float2half(f);
    }
}

// --------------------------------------------------------------------
// PyTorch binding
// --------------------------------------------------------------------
torch::Tensor l2norm_forward(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kHalf, "input must be float16");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");

    auto output = torch::empty_like(input);
    const int batch = input.size(0);
    const int dim   = input.size(1);

    const dim3 blocks(batch);
    const dim3 threads(BLOCK_SIZE);

    l2norm_kernel<BLOCK_SIZE><<<blocks, threads>>>(
        reinterpret_cast<const __half*>(input.data_ptr()),
        reinterpret_cast<__half*>(output.data_ptr()),
        dim
    );

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA kernel launch failed: ", cudaGetErrorString(err));
    }
    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("l2norm_forward", &l2norm_forward, "Row‑wise L2 normalisation (FP16)");
}
'''

# --------------------------------------------------------------------
# Compile the extension
# --------------------------------------------------------------------
_ext = load_inline(
    name='l2norm_ext',
    cpp_sources='',
    cuda_sources=cuda_source,
    functions=['l2norm_forward'],
    verbose=False,
)

# --------------------------------------------------------------------
# Model that uses the custom kernel
# --------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model.
    Performs row‑wise L2 normalisation on FP16 tensors using a custom CUDA kernel.
    """
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure tensor is on CUDA, contiguous and half‑precision
        if not x.is_cuda:
            x = x.cuda()
        if x.dtype != torch.float16:
            x = x.half()
        x = x.contiguous()
        # Call the compiled kernel
        return _ext.l2norm_forward(x)

# --------------------------------------------------------------------
# Example usage (mirrors the reference script)
# --------------------------------------------------------------------
if __name__ == "__main__":
    batch_size = 32768
    dim = 65535

    def get_inputs():
        x = torch.rand(batch_size, dim, device='cuda', dtype=torch.float16)
        return [x]

    model = ModelNew().cuda()
    x = get_inputs()[0]
    out = model(x)
